export default {"file":"teachers.html","title":"Teacher Operations","htmlClass":"","bodyClass":"","body":"\r\n    <div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n        <section class=\"dots-container\" aria-label=\"Loading page\">\r\n            <div class=\"dot\"></div>\r\n            <div class=\"dot\"></div>\r\n            <div class=\"dot\"></div>\r\n            <div class=\"dot\"></div>\r\n            <div class=\"dot\"></div>\r\n        </section>\r\n    </div>\r\n    <div class=\"page-shell\">\r\n        <header class=\"panel hero\">\r\n            <div class=\"hero-copy\">\r\n                <div class=\"eyebrow\">Faculty Operations</div>\r\n                <h1 id=\"heroSchoolName\">Teacher Operations Hub</h1>\r\n                <p id=\"heroSubtitle\">Create teacher accounts, mark daily attendance with check-in and check-out time,\r\n                    and manage month-wise salary payout records.</p>\r\n            </div>\r\n            <div class=\"hero-actions\">\r\n                <button type=\"button\" class=\"btn btn-light\" onclick=\"goBack()\">Back to Dashboard</button>\r\n            </div>\r\n        </header>\r\n\r\n        <section class=\"stats-grid\">\r\n            <div class=\"panel stat-card\">\r\n                <div class=\"stat-label\">Total Teachers</div>\r\n                <div class=\"stat-value\" id=\"teacherCountStat\">0</div>\r\n                <div class=\"stat-note\">Active teacher accounts under this school panel.</div>\r\n            </div>\r\n            <div class=\"panel stat-card\">\r\n                <div class=\"stat-label\">Today Present</div>\r\n                <div class=\"stat-value\" id=\"todayPresentStat\">0</div>\r\n                <div class=\"stat-note\" id=\"todayAttendanceNote\">Attendance appears after the selected date is loaded.\r\n                </div>\r\n            </div>\r\n            <div class=\"panel stat-card\">\r\n                <div class=\"stat-label\">This Month Paid</div>\r\n                <div class=\"stat-value\" id=\"monthlyPaidStat\">₹0</div>\r\n                <div class=\"stat-note\">Total salary already paid in the selected salary month.</div>\r\n            </div>\r\n            <div class=\"panel stat-card\">\r\n                <div class=\"stat-label\">Pending Payroll</div>\r\n                <div class=\"stat-value\" id=\"monthlyPendingStat\">₹0</div>\r\n                <div class=\"stat-note\">Remaining salary balance across generated salary records.</div>\r\n            </div>\r\n        </section>\r\n\r\n        <section class=\"panel tabs-panel\">\r\n            <div class=\"tabs\">\r\n                <button type=\"button\" class=\"tab-btn active\" data-tab=\"directory\"\r\n                    onclick=\"switchTab('directory')\">Teacher Accounts</button>\r\n                <button type=\"button\" class=\"tab-btn\" data-tab=\"attendance\" onclick=\"switchTab('attendance')\">Daily\r\n                    Attendance</button>\r\n                <button type=\"button\" class=\"tab-btn\" data-tab=\"salary\" onclick=\"switchTab('salary')\">Salary\r\n                    Desk</button>\r\n            </div>\r\n        </section>\r\n\r\n        <section class=\"panel tab-panel active\" id=\"directoryTab\">\r\n            <div class=\"section-grid\">\r\n                <div class=\"section-card\">\r\n                    <div class=\"section-header\">\r\n                        <div>\r\n                            <h2>Create Teacher Account</h2>\r\n                            <p>Assign login access, class responsibility, and base monthly salary in one go.</p>\r\n                        </div>\r\n                    </div>\r\n                    <form id=\"addTeacherForm\">\r\n                        <div class=\"form-grid\">\r\n                            <div class=\"field\">\r\n                                <label for=\"teacherName\">Teacher Name</label>\r\n                                <input type=\"text\" id=\"teacherName\" placeholder=\"Enter full name\" required>\r\n                            </div>\r\n                            <div class=\"field\">\r\n                                <label for=\"teacherEmail\">Email Address</label>\r\n                                <input type=\"email\" id=\"teacherEmail\" placeholder=\"teacher@school.com\" required>\r\n                            </div>\r\n                            <div class=\"field\">\r\n                                <label for=\"teacherPassword\">Password</label>\r\n                                <input type=\"password\" id=\"teacherPassword\" placeholder=\"Minimum 6 characters\"\r\n                                    minlength=\"6\" required>\r\n                            </div>\r\n                            <div class=\"field\">\r\n                                <label for=\"teacherSalary\">Monthly Salary</label>\r\n                                <input type=\"number\" id=\"teacherSalary\" placeholder=\"45000\" min=\"0\" required>\r\n                            </div>\r\n                            <div class=\"field\">\r\n                                <label for=\"classSelect\">Assigned Class</label>\r\n                                <select id=\"classSelect\" onchange=\"updateSections()\">\r\n                                    <option value=\"\">Select class</option>\r\n                                </select>\r\n                            </div>\r\n                            <div class=\"field\">\r\n                                <label for=\"sectionSelect\">Assigned Section</label>\r\n                                <select id=\"sectionSelect\">\r\n                                    <option value=\"\">Select section</option>\r\n                                </select>\r\n                            </div>\r\n                            <div class=\"field full\">\r\n                                <label>Class Teacher Assignments</label>\r\n                                <div class=\"assignment-picker\">\r\n                                    <button type=\"button\" class=\"btn btn-secondary\" onclick=\"addTeacherAssignment()\">Add\r\n                                        Selected Class</button>\r\n                                    <div id=\"teacherAssignmentsList\" class=\"assignment-list\"></div>\r\n                                </div>\r\n                                <div class=\"helper-text\">Add one or more class-section responsibilities. Teacher will\r\n                                    see only these classes in their panel.</div>\r\n                            </div>\r\n                            <div class=\"field full\">\r\n                                <label>Assigned Subjects for Teaching</label>\r\n                                <div class=\"assignment-picker\">\r\n                                    <div style=\"display:flex; gap:8px; width:100%;\">\r\n                                        <select id=\"teacherSubjectSelect\" style=\"flex:1;\">\r\n                                            <option value=\"\">Select subject</option>\r\n                                        </select>\r\n                                        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"addDraftTeacherSubject()\">Add Subject</button>\r\n                                    </div>\r\n                                    <div id=\"teacherSubjectsList\" class=\"assignment-list\" style=\"margin-top:8px;\"></div>\r\n                                </div>\r\n                                <div class=\"helper-text\">Assign one or multiple subjects for this teacher. These subjects will link to this teacher in timetable slots.</div>\r\n                            </div>\r\n                            <div class=\"field full\">\r\n                                <label for=\"teacherPhoto\">Teacher Photo</label>\r\n                                <input type=\"file\" id=\"teacherPhoto\" accept=\"image/*\">\r\n                                <div class=\"helper-text\">Optional. The photo appears on the teacher dashboard and admin\r\n                                    teacher panel.</div>\r\n                            </div>\r\n                            <div class=\"field full\">\r\n                                <button type=\"submit\" class=\"btn btn-primary\" id=\"createTeacherBtn\">Create Teacher\r\n                                    Account</button>\r\n                            </div>\r\n                        </div>\r\n                    </form>\r\n                </div>\r\n\r\n                <div class=\"section-card\">\r\n                    <div class=\"section-header\">\r\n                        <div>\r\n                            <h2>Quick School Snapshot</h2>\r\n                            <p>The current teacher and payroll summary refreshes as you work.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"summary-box\">\r\n                        <div class=\"pill-row\">\r\n                            <span class=\"pill\" id=\"schoolNamePill\">School panel</span>\r\n                            <span class=\"pill\" id=\"salaryMonthPill\">Salary month</span>\r\n                        </div>\r\n                        <div class=\"summary-grid\">\r\n                            <div class=\"mini-stat\"><span>Teachers</span><strong id=\"summaryTeacherCount\">0</strong>\r\n                            </div>\r\n                            <div class=\"mini-stat\"><span>Attendance Marked</span><strong\r\n                                    id=\"summaryAttendanceMarked\">0</strong></div>\r\n                            <div class=\"mini-stat\"><span>Paid Out</span><strong id=\"summaryPaidOut\">₹0</strong></div>\r\n                            <div class=\"mini-stat\"><span>Pending</span><strong id=\"summaryPendingOut\">₹0</strong></div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"policy-card\">\r\n                        <div class=\"policy-header\">\r\n                            <div class=\"policy-icon\"></div>\r\n                            <div>\r\n                                <div class=\"policy-title\">No Deduction Absent Policy</div>\r\n                                <div class=\"policy-subtitle\">Absent days up to this limit won't deduct salary</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"form-grid\" style=\"margin-top:14px;\">\r\n                            <div class=\"field\">\r\n                                <label for=\"noDeductionDays\">No Deduction Absent Days / Month</label>\r\n                                <input type=\"number\" id=\"noDeductionDays\" placeholder=\"e.g. 2\" min=\"0\" max=\"31\"\r\n                                    value=\"0\">\r\n                            </div>\r\n                            <div class=\"field\">\r\n                                <label>&nbsp;</label>\r\n                                <button type=\"button\" class=\"btn btn-primary\" onclick=\"saveLeavePolicy()\">Save\r\n                                    Policy</button>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"helper-text info-note\" id=\"leavePolicyNote\">\r\n                            Currently: <strong id=\"currentLeavePolicy\">0 days</strong> absent days per month are allowed\r\n                            without deduction. Extra absent days will be deducted from salary.\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"helper-text info-note\">Removing a teacher hides them from active attendance and salary\r\n                        generation, while keeping their old attendance and salary records searchable in Removed\r\n                        Teachers.</div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"section-card\">\r\n                <div class=\"section-header\">\r\n                    <div>\r\n                        <h3>Teachers Directory</h3>\r\n                        <p>Update monthly salary, jump straight into salary management, edit teacher details, or remove\r\n                            a teacher record.</p>\r\n                    </div>\r\n                    <div class=\"search-wrap\">\r\n                        <input type=\"text\" id=\"teacherSearch\"\r\n                            placeholder=\"Search by name, email, ID, class, section or status\">\r\n                        <div class=\"button-row top-gap teacher-directory-switch\">\r\n                            <button type=\"button\" class=\"btn btn-primary\" id=\"activeTeacherViewBtn\"\r\n                                onclick=\"setTeacherDirectoryView('active')\">Active Teachers</button>\r\n                            <button type=\"button\" class=\"btn btn-light\" id=\"removedTeacherViewBtn\"\r\n                                onclick=\"setTeacherDirectoryView('removed')\">Removed Teachers</button>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div id=\"teachersList\" class=\"teacher-list\"></div>\r\n            </div>\r\n        </section>\r\n\r\n        <section class=\"panel tab-panel\" id=\"attendanceTab\">\r\n            <div class=\"section-card\">\r\n                <div class=\"section-header\">\r\n                    <div>\r\n                        <h2>Teacher Daily Attendance</h2>\r\n                        <p>Mark teacher attendance day by day, store check-in and check-out time, and keep remarks with\r\n                            the record.</p>\r\n                    </div>\r\n                    <!-- ─── NEW: Monthly Report Button ─── -->\r\n                    <div>\r\n                        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"openMonthlyReportModal()\">Monthly\r\n                            Report</button>\r\n                    </div>\r\n                </div>\r\n                <div class=\"attendance-toolbar\">\r\n                    <div class=\"field\">\r\n                        <label for=\"attendanceDate\">Attendance Date</label>\r\n                        <input type=\"date\" id=\"attendanceDate\">\r\n                    </div>\r\n                    <div class=\"field\">\r\n                        <label>Bulk Status</label>\r\n                        <div class=\"button-row\">\r\n                            <button type=\"button\" class=\"btn btn-secondary\"\r\n                                onclick=\"fillTeacherAttendanceStatus('Present')\">All Present</button>\r\n                            <button type=\"button\" class=\"btn btn-warning\"\r\n                                onclick=\"fillTeacherAttendanceStatus('Half Day')\">All Half Day</button>\r\n                            <button type=\"button\" class=\"btn btn-danger\"\r\n                                onclick=\"fillTeacherAttendanceStatus('Absent')\">All Absent</button>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"field\">\r\n                        <label>Quick Time</label>\r\n                        <div class=\"button-row\">\r\n                            <button type=\"button\" class=\"btn btn-light\" onclick=\"setBulkCheckInNow()\">Set Check-In\r\n                                Now</button>\r\n                            <button type=\"button\" class=\"btn btn-light\" onclick=\"clearBulkTimes()\">Clear Times</button>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"field\">\r\n                        <label>Actions</label>\r\n                        <div class=\"button-row\">\r\n                            <button type=\"button\" class=\"btn btn-secondary\"\r\n                                onclick=\"loadTeacherAttendanceForDate()\">Reload Date</button>\r\n                            <button type=\"button\" class=\"btn btn-warning\" onclick=\"markRemainingTeachersAbsent()\">Mark\r\n                                Remaining Absent</button>\r\n                            <button type=\"button\" class=\"btn btn-success\" onclick=\"saveTeacherAttendance()\">Save\r\n                                Attendance</button>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"mini-grid attendance-mini-grid\">\r\n                    <div class=\"mini-stat\"><span>Present</span><strong id=\"attendancePresentCount\">0</strong></div>\r\n                    <div class=\"mini-stat\"><span>Half Day</span><strong id=\"attendanceHalfCount\">0</strong></div>\r\n                    <div class=\"mini-stat\"><span>Absent</span><strong id=\"attendanceAbsentCount\">0</strong></div>\r\n                </div>\r\n\r\n                <div id=\"teacherAttendanceList\" class=\"attendance-list\"></div>\r\n            </div>\r\n        </section>\r\n\r\n        <section class=\"panel tab-panel\" id=\"salaryTab\">\r\n            <div class=\"section-grid\">\r\n                <div class=\"section-card\">\r\n                    <div class=\"section-header\">\r\n                        <div>\r\n                            <h2>Monthly Salary Generator</h2>\r\n                            <p>Generate payroll from monthly salary plus marked attendance. Absent days follow the\r\n                                no-deduction limit, and half-day deducts half-day value.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"salary-toolbar\">\r\n                        <div class=\"field\">\r\n                            <label for=\"salaryTeacherSelect\">Teacher</label>\r\n                            <select id=\"salaryTeacherSelect\">\r\n                                <option value=\"\">Select teacher</option>\r\n                            </select>\r\n                        </div>\r\n                        <div class=\"field\">\r\n                            <label for=\"salaryMonth\">Salary Month</label>\r\n                            <input type=\"month\" id=\"salaryMonth\">\r\n                        </div>\r\n                        <div class=\"field\">\r\n                            <label for=\"salaryStatusFilter\">Payment Status</label>\r\n                            <select id=\"salaryStatusFilter\">\r\n                                <option value=\"\">All records</option>\r\n                                <option value=\"due\">Due / unpaid</option>\r\n                                <option value=\"unpaid\">Unpaid only</option>\r\n                                <option value=\"partial\">Partial due</option>\r\n                                <option value=\"paid\">Paid only</option>\r\n                            </select>\r\n                        </div>\r\n                        <div class=\"field\">\r\n                            <label>Actions</label>\r\n                            <div class=\"button-row\">\r\n                                <button type=\"button\" class=\"btn btn-primary\"\r\n                                    onclick=\"generateSelectedSalaryRecord()\">Generate Selected</button>\r\n                                <button type=\"button\" class=\"btn btn-secondary\"\r\n                                    onclick=\"loadSalaryPreview()\">Preview</button>\r\n                                <button type=\"button\" class=\"btn btn-warning\"\r\n                                    onclick=\"generateAllSalaryRecords()\">Generate All</button>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    <div id=\"salaryPreviewBox\" class=\"summary-box\">\r\n                        <strong>Select a teacher and month to preview salary.</strong>\r\n                        <div class=\"helper-text top-gap\">Generated salary records stay editable through payment history\r\n                            below.</div>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"section-card\">\r\n                    <div class=\"section-header\">\r\n                        <div>\r\n                            <h2>Salary Payment Entry</h2>\r\n                            <p>Add salary payments to the selected salary record. Status updates automatically to paid\r\n                                or partial paid.</p>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"form-grid\">\r\n                        <div class=\"field\">\r\n                            <label for=\"paymentAmount\">Payment Amount</label>\r\n                            <input type=\"number\" id=\"paymentAmount\" placeholder=\"0\" min=\"0\">\r\n                        </div>\r\n                        <div class=\"field\">\r\n                            <label for=\"paymentDate\">Payment Date</label>\r\n                            <input type=\"date\" id=\"paymentDate\">\r\n                        </div>\r\n                        <div class=\"field full\">\r\n                            <label for=\"paymentNote\">Payment Note</label>\r\n                            <textarea id=\"paymentNote\" placeholder=\"Optional note for this salary payment\"></textarea>\r\n                        </div>\r\n                        <div class=\"field full\">\r\n                            <button type=\"button\" class=\"btn btn-success\" id=\"recordPaymentBtn\"\r\n                                onclick=\"recordSalaryPayment()\">Record Salary Payment</button>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"helper-text top-gap\" id=\"activeSalaryHint\">Pick a generated salary record from the list\r\n                        below before recording payment.</div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"section-card\">\r\n                <div class=\"section-header\">\r\n                    <div>\r\n                        <h3>Salary Records</h3>\r\n                        <p>Inspect attendance-linked salary, payment history, and remaining payable balance.</p>\r\n                    </div>\r\n                </div>\r\n                <div id=\"salaryRecordsList\" class=\"salary-records\"></div>\r\n            </div>\r\n        </section>\r\n    </div>\r\n\r\n    <!-- ═══════════════════════════════════════════════\r\n     MODAL: Monthly Attendance Report\r\n═══════════════════════════════════════════════ -->\r\n    <div id=\"teacherQrModal\" class=\"modal-overlay\" style=\"display:none;\" onclick=\"closeTeacherQrModal(event)\">\r\n        <div class=\"modal-box qr-modal-box\" onclick=\"event.stopPropagation()\">\r\n            <div class=\"modal-header\">\r\n                <div>\r\n                    <h2 id=\"qrModalTitle\">Teacher QR</h2>\r\n                    <p id=\"qrModalSubtitle\">Scan this QR from the teacher dashboard to mark today's attendance.</p>\r\n                </div>\r\n                <button type=\"button\" class=\"btn btn-light modal-close\" onclick=\"closeTeacherQrModal()\">Close</button>\r\n            </div>\r\n            <div class=\"field top-gap\">\r\n                <label for=\"teacherQrMode\">QR Attendance Type</label>\r\n                <select id=\"teacherQrMode\">\r\n                    <option value=\"checkin\">Check-In Present</option>\r\n                    <option value=\"halfday\">Half Day Check-Out</option>\r\n                    <option value=\"checkout\">Check-Out</option>\r\n                </select>\r\n            </div>\r\n            <div class=\"button-row top-gap\">\r\n                <button type=\"button\" class=\"btn btn-primary\" id=\"confirmGenerateQrBtn\"\r\n                    onclick=\"confirmGenerateTeacherAttendanceQr()\">Generate Selected QR</button>\r\n            </div>\r\n            <div class=\"qr-display\">\r\n                <img id=\"teacherQrImage\" alt=\"Teacher attendance QR code\">\r\n                <div class=\"qr-code-text\" id=\"teacherQrCodeText\"></div>\r\n            </div>\r\n            <div class=\"helper-text top-gap\" id=\"teacherQrMeta\"></div>\r\n        </div>\r\n    </div>\r\n\r\n    <div id=\"monthlyReportModal\" class=\"modal-overlay\" style=\"display:none;\" onclick=\"closeMonthlyReportModal(event)\">\r\n        <div class=\"modal-box\" onclick=\"event.stopPropagation()\">\r\n            <div class=\"modal-header\">\r\n                <div>\r\n                    <h2> Monthly Attendance Report</h2>\r\n                    <p>Full month-wise attendance breakdown for each teacher.</p>\r\n                </div>\r\n                <button type=\"button\" class=\"btn btn-light modal-close\" onclick=\"closeMonthlyReportModal()\">✕\r\n                    Close</button>\r\n            </div>\r\n            <div class=\"modal-toolbar\">\r\n                <div class=\"field\">\r\n                    <label for=\"reportMonth\">Select Month</label>\r\n                    <input type=\"month\" id=\"reportMonth\">\r\n                </div>\r\n                <div class=\"field\">\r\n                    <label for=\"reportTeacherFilter\">Filter by Teacher</label>\r\n                    <select id=\"reportTeacherFilter\">\r\n                        <option value=\"\">All Teachers</option>\r\n                    </select>\r\n                </div>\r\n                <div class=\"field\">\r\n                    <label>&nbsp;</label>\r\n                    <button type=\"button\" class=\"btn btn-primary\" onclick=\"loadMonthlyReport()\">Load Report</button>\r\n                </div>\r\n            </div>\r\n            <div id=\"monthlyReportContent\" class=\"report-content\">\r\n                <div class=\"empty-state\">Select a month and click Load Report to see attendance summary.</div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- ═══════════════════════════════════════════════\r\n     MODAL: Edit Teacher Details\r\n═══════════════════════════════════════════════ -->\r\n    <div id=\"editTeacherClassesModal\" class=\"modal-overlay\" hidden aria-hidden=\"true\" role=\"dialog\" aria-modal=\"true\"\r\n        aria-labelledby=\"editTeacherClassesTitle\">\r\n        <div class=\"modal-box\">\r\n            <div class=\"modal-header\">\r\n                <div>\r\n                    <h2 id=\"editTeacherClassesTitle\">Edit Assigned Classes</h2>\r\n                    <p id=\"editTeacherClassesSubtitle\">Add or remove class-section assignments only.</p>\r\n                </div>\r\n                <button type=\"button\" class=\"teacher-dialog-close\" onclick=\"closeEditTeacherClassesModal()\"\r\n                    aria-label=\"Close class editor\" title=\"Close\">&times;</button>\r\n            </div>\r\n            <input type=\"hidden\" id=\"editClassesTeacherUid\">\r\n            <div class=\"form-grid\" style=\"margin-top:18px;\">\r\n                <div class=\"field\">\r\n                    <label for=\"editClassesClassSelect\">Assigned Class</label>\r\n                    <select id=\"editClassesClassSelect\" onchange=\"updateEditClassSections()\">\r\n                        <option value=\"\">Select class</option>\r\n                    </select>\r\n                </div>\r\n                <div class=\"field\">\r\n                    <label for=\"editClassesSectionSelect\">Assigned Section</label>\r\n                    <select id=\"editClassesSectionSelect\">\r\n                        <option value=\"\">Select section</option>\r\n                    </select>\r\n                </div>\r\n                <div class=\"field full\">\r\n                    <label>Current Assignments</label>\r\n                    <div class=\"assignment-picker\">\r\n                        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"addTeacherClassOnlyAssignment()\">Add\r\n                            Selected Class</button>\r\n                        <div id=\"editClassesAssignmentsList\" class=\"assignment-list\"></div>\r\n                    </div>\r\n                    <div class=\"helper-text\">Only assigned classes will change. Name, email, salary, photo and other\r\n                        details stay untouched.</div>\r\n                </div>\r\n                <div class=\"field full\">\r\n                    <div class=\"edit-teacher-actions\">\r\n                        <button type=\"button\" class=\"btn btn-light\"\r\n                            onclick=\"closeEditTeacherClassesModal()\">Cancel</button>\r\n                        <button type=\"button\" class=\"btn btn-success\" id=\"saveEditClassesBtn\"\r\n                            onclick=\"saveTeacherClassAssignments()\">Save Classes</button>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div id=\"editTeacherModal\" class=\"modal-overlay\" hidden aria-hidden=\"true\" role=\"dialog\" aria-modal=\"true\"\r\n        aria-labelledby=\"editTeacherModalTitle\">\r\n        <div class=\"modal-box\">\r\n            <div class=\"modal-header\">\r\n                <div>\r\n                    <h2 id=\"editTeacherModalTitle\">Edit Teacher Details</h2>\r\n                    <p>Update name, email, class, and section assignments.</p>\r\n                </div>\r\n                <button type=\"button\" class=\"teacher-dialog-close\" id=\"editTeacherCloseBtn\"\r\n                    aria-label=\"Close edit teacher dialog\" title=\"Close\">&times;</button>\r\n            </div>\r\n            <input type=\"hidden\" id=\"editTeacherUid\">\r\n            <input type=\"hidden\" id=\"removeTeacherPhotoFlag\" value=\"0\">\r\n            <div class=\"form-grid\" style=\"margin-top:18px;\">\r\n                <div class=\"field full\">\r\n                    <label>Teacher Photo</label>\r\n                    <div class=\"teacher-photo-editor\">\r\n                        <button type=\"button\" class=\"teacher-photo-preview\" id=\"editTeacherPhotoPreview\"\r\n                            onclick=\"previewCurrentTeacherPhoto()\">No photo</button>\r\n                        <div class=\"teacher-photo-controls\">\r\n                            <input type=\"file\" id=\"editTeacherPhoto\" accept=\"image/*\"\r\n                                onchange=\"previewEditedTeacherPhoto()\">\r\n                            <div class=\"button-row\">\r\n                                <button type=\"button\" class=\"btn btn-light\" onclick=\"previewCurrentTeacherPhoto()\">View\r\n                                    Photo</button>\r\n                                <button type=\"button\" class=\"btn btn-secondary\" onclick=\"removeTeacherPhoto()\">Remove\r\n                                    Photo</button>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"field\">\r\n                    <label for=\"editTeacherName\">Teacher Name</label>\r\n                    <input type=\"text\" id=\"editTeacherName\" placeholder=\"Full name\" required>\r\n                </div>\r\n                <div class=\"field\">\r\n                    <label for=\"editTeacherEmail\">Email Address</label>\r\n                    <input type=\"email\" id=\"editTeacherEmail\" placeholder=\"teacher@school.com\" required>\r\n                </div>\r\n                <div class=\"field\">\r\n                    <label for=\"editClassSelect\">Assigned Class</label>\r\n                    <select id=\"editClassSelect\" onchange=\"updateEditSections()\">\r\n                        <option value=\"\">Select class</option>\r\n                    </select>\r\n                </div>\r\n                <div class=\"field\">\r\n                    <label for=\"editSectionSelect\">Assigned Section</label>\r\n                    <select id=\"editSectionSelect\">\r\n                        <option value=\"\">Select section</option>\r\n                    </select>\r\n                </div>\r\n                <div class=\"field full\">\r\n                    <label>Class Teacher Assignments</label>\r\n                    <div class=\"assignment-picker\">\r\n                        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"addEditTeacherAssignment()\">Add\r\n                            Selected Class</button>\r\n                        <div id=\"editTeacherAssignmentsList\" class=\"assignment-list\"></div>\r\n                    </div>\r\n                    <div class=\"helper-text\">Use this when a teacher is class teacher for more than one class-section.\r\n                    </div>\r\n                </div>\r\n                <div class=\"field full\">\r\n                    <label>Assigned Subjects for Teaching</label>\r\n                    <div class=\"assignment-picker\">\r\n                        <div style=\"display:flex; gap:8px; width:100%;\">\r\n                            <select id=\"editTeacherSubjectSelect\" style=\"flex:1;\">\r\n                                <option value=\"\">Select subject</option>\r\n                            </select>\r\n                            <button type=\"button\" class=\"btn btn-secondary\" onclick=\"addEditTeacherSubject()\">Add Subject</button>\r\n                        </div>\r\n                        <div id=\"editTeacherSubjectsList\" class=\"assignment-list\" style=\"margin-top:8px;\"></div>\r\n                    </div>\r\n                    <div class=\"helper-text\">Assign one or multiple subjects taught by this teacher.</div>\r\n                </div>\r\n                <div class=\"field full\">\r\n                    <div class=\"edit-teacher-actions\">\r\n                        <button type=\"button\" class=\"btn btn-light\" id=\"editTeacherCancelBtn\">Cancel</button>\r\n                        <button type=\"button\" class=\"btn btn-success\" id=\"saveEditTeacherBtn\"\r\n                            onclick=\"saveEditedTeacher()\">Save Changes</button>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div class=\"helper-text top-gap\">Note: Changing email here updates the Firestore profile only. Firebase Auth\r\n                email is not changed automatically.</div>\r\n        </div>\r\n    </div>\r\n\r\n    <div id=\"photoPreviewModal\" class=\"modal-overlay\" style=\"display:none;\" onclick=\"closePhotoPreviewModal(event)\">\r\n        <div class=\"modal-box photo-preview-box\" onclick=\"event.stopPropagation()\">\r\n            <div class=\"modal-header\">\r\n                <div>\r\n                    <h2 id=\"photoPreviewTitle\">Photo</h2>\r\n                    <p>Click outside or close to return.</p>\r\n                </div>\r\n                <button type=\"button\" class=\"btn btn-light modal-close\"\r\n                    onclick=\"closePhotoPreviewModal()\">Close</button>\r\n            </div>\r\n            <div class=\"photo-preview-stage\">\r\n                <img id=\"photoPreviewImage\" alt=\"Preview\">\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <script src=\"school-branding.js\"></script>\r\n    <script type=\"module\" src=\"teachers-ops.js\"></script>\r\n    <script type=\"module\" src=\"access-control.js\"></script>\r\n    <script src=\"schoolix-polish.js\" defer></script>\r\n    <script src=\"admin-shell.js?v=navbar-20260721\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"href":"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap","rel":"stylesheet"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"teachers-ops.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n        (function () {\r\n            var root = document.documentElement;\r\n            root.classList.add(\"sx-page-loading\");\r\n            window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n            function markEarlyReady(reason) {\r\n                window.SchoolixPageLoaderEarly.ready = true;\r\n                window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n                try {\r\n                    window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n                } catch (_) { }\r\n            }\r\n\r\n            function afterFirstPaint(reason) {\r\n                requestAnimationFrame(function () {\r\n                    requestAnimationFrame(function () { markEarlyReady(reason); });\r\n                });\r\n            }\r\n\r\n            function emergencyHide() {\r\n                if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n                root.classList.remove(\"sx-page-loading\");\r\n                root.classList.add(\"sx-page-loaded\");\r\n                var loader = document.getElementById(\"sxPageLoader\");\r\n                if (!loader) return;\r\n                loader.classList.add(\"is-hidden\");\r\n                setTimeout(function () { loader.remove(); }, 260);\r\n            }\r\n\r\n            if (document.readyState === \"loading\") {\r\n                document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n            } else {\r\n                afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n            }\r\n            window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n            setTimeout(emergencyHide, 3200);\r\n        }());\r\n    "},{"attributes":{"src":"school-branding.js"},"text":""},{"attributes":{"type":"module","src":"teachers-ops.js"},"text":""},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
